SELECT product_id, product_code, product_name, service_code, total_count, price FROM erp_bookstore_product WHERE is_active = 1
AND service_code = #{serviceCode}
ORDER BY price ASC

SELECT product_id, product_code, product_name, service_code, total_count, price
FROM erp_bookstore_product
WHERE product_id = #{productId}

SELECT TOP 1 
FROM erp_bookstore_payment
WHERE student_id = #{studentId}
  AND service_code = #{serviceCode}
  AND billing_ym = #{billingYm}
  AND status IN ('READY', 'PAID')
ORDER BY CASE status WHEN 'PAID' THEN 0 ELSE 1 END, requested_at DESC

SELECT COUNT(*)
FROM erp_bookstore_payment
WHERE tid = #{tid}
  AND order_no <> #{orderNo}

      AND (group_order_no IS NULL OR group_order_no <> #{groupOrderNo})

SELECT FROM erp_bookstore_payment p LEFT JOIN erp_student s ON s.student_id = p.student_id WHERE p.student_id IN
#{studentId}
AND p.status NOT IN ('READY', 'CLOSED') ORDER BY p.requested_at DESC

mapper.update:
UPDATE erp_bookstore_payment
SET needs_review  = 1,
    review_reason = #{reason}
WHERE order_no = #{orderNo}

UPDATE erp_bookstore_payment
SET refund_requested_at = NULL
WHERE payment_id = #{paymentId}

UPDATE erp_bookstore_payment
SET closed_recheck_at = DATEADD(HOUR, 9, GETUTCDATE())
WHERE order_no = #{orderNo}
